import{_ as p,a0 as l,w as r,s as n,I as e,x as s,a1 as o,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何恢復丟棄的 git stash 數據 | LCTT x X-CMD","titleTemplate":false,"description":"如何恢復丟棄的 git stash 數據 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何恢復丟棄的 git stash 數據 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何恢復丟棄的 git stash 數據 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170818 How to recover from a git mistake","title":"如何恢復丟棄的 git stash 數據","tag":"201708","desc":""},"relativePath":"201708/20170818 How to recover from a git mistake.md","filePath":"[post].md"}'),g={name:"201708/20170818 How to recover from a git mistake.md"};function u(m,t,f,h,c,k){const i=l("Link");return r(),n("div",null,[t[24]||(t[24]=e("h1",{id:"如何恢復丟棄的-git-stash-數據",tabindex:"-1"},[s("如何恢復丟棄的 git stash 數據 "),e("a",{class:"header-anchor",href:"#如何恢復丟棄的-git-stash-數據","aria-label":"Permalink to “如何恢復丟棄的 git stash 數據”"},"​")],-1)),t[25]||(t[25]=e("blockquote",null,[e("p",null,"不要讓 git 命令中的錯誤抹去數天的工作")],-1)),t[26]||(t[26]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bubblehands_fromRHT_520_0612LL.png?itok=_iQ2dO3S",alt:"How to recover from a git mistake",title:"How to recover from a git mistake"})],-1)),e("p",null,[t[1]||(t[1]=s("今天我的同事幾乎失去了他在四天工作中所做的一切。由於不正確的 ",-1)),t[2]||(t[2]=e("code",null,"git",-1)),t[3]||(t[3]=s(" 命令，他把保存在 ",-1)),o(i,{href:"https://www.git-scm.com/docs/git-stash"},{default:a(()=>[...t[0]||(t[0]=[s("stash",-1)])]),_:1}),t[4]||(t[4]=s(" 中的更改刪除了。在這悲傷的情節之後，我們試圖尋找一種恢復他所做工作的方法，而且我們做到了！",-1))]),t[27]||(t[27]=d('<p>首先警告一下：當你在實現一個大功能時，請將它分成小塊並定期提交。長時間工作而不做提交併不是一個好主意。</p><p>現在我們已經搞定了那個錯誤，下面就演示一下怎樣從 stash 中恢復誤刪的更改。</p><p>我用作示例的倉庫中，只有一個源文件 “main.c”，如下所示：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_01.jpeg" alt="Repository with one source file" title="Repository with one source file"></p><p>它只有一次提交，即 “Initial commit”：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_02.jpeg" alt="One commit" title="One commit"></p><p>該文件的第一個版本是：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_03.jpeg" alt="First version of the file" title="First version of the file"></p><p>我將在文件中寫一些代碼。對於這個例子，我並不需要做什麼大的改動，只需要有什麼東西放進 stash 中即可，所以我們僅僅增加一行。“git diff” 的輸出如下：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_04.jpeg" alt="git-diff output " title="git-diff output "></p><p>現在，假設我想從遠程倉庫中拉取一些新的更改，當時還不打算提交我自己的更改。於是，我決定先 stash 它，等拉取遠程倉庫中的更改後，再把我的更改恢復應用到主分支上。我執行下面的命令將我的更改移動到 stash 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash</span></span></code></pre></div><p>使用命令 <code>git stash list</code> 查看 stash，在這裏能看到我的更改：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_06.jpeg" alt="Output of changes in our stash" title="Output of changes in our stash"></p><p>我的代碼已經在一個安全的地方，而且主分支目前是乾淨的（使用命令 <code>git status</code> 檢查）。現在我只需要拉取遠程倉庫的更改，然後把我的更改恢復應用到主分支上，而且我也應該是這麼做的。</p><p>但是我錯誤地執行了命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash drop</span></span></code></pre></div><p>它刪除了 stash，而不是執行了下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash pop</span></span></code></pre></div><p>這條命令會在從棧中刪除 stash 之前應用它。如果我再次執行命令 <code>git stash list</code>，就能看到在沒有從棧中將更改恢復到主分支的之前，我就刪除了它。OMG！接下來怎麼辦？</p><p>好消息是：<code>git</code> 並沒有刪除包含了我的更改的對象，它只是移除了對它的引用。為了證明這一點，我使用命令 <code>git fsck</code>，它會驗證資料庫中對象的連接和有效性。這是我對該倉庫執行了 <code>git fsck</code> 之後的輸出：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_07.jpeg" alt="Output after executing the git-fsck command on the repository" title="Output after executing the git-fsck command on the repository"></p><p>由於使用了參數 <code>--unreachable</code>，我讓 <code>git-fsck</code> 顯示出所有不可訪問的對象。正如你看到的，它顯示並沒有不可訪問的對象。而當我從 stash 中刪除了我的更改之後，再次執行相同的指令，得到了一個不一樣的輸出：</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_08.jpeg" alt="Output after dropping changes on stash" title="Output after dropping changes on stash"></p><p>現在有三個不可訪問對象。那麼哪一個才是我的更改呢？實際上，我不知道。我需要通過執行命令 <code>git show</code> 來搜索每一個對象。</p><p><img src="https://opensource.com/sites/default/files/u128651/missing_data_from_stash_09.jpeg" alt="Output after executing the git-show command " title="Output after executing the git-show command "></p><p>就是它！ID 號 <code>95ccbd927ad4cd413ee2a28014c81454f4ede82c</code> 對應了我的更改。現在我已經找到了丟失的更改，我可以恢復它。其中一種方法是將此 ID 取出來放進一個新的分支，或者直接提交它。如果你得到了你的更改對象的 ID 號，就可以決定以最好的方式，將更改再次恢復應用到主分支上。對於這個例子，我使用 <code>git stash</code> 將更改恢復到我的主分支上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash apply 95ccbd927ad4cd413ee2a28014c81454f4ede82c</span></span></code></pre></div><p>另外需要重點記住的是 <code>git</code> 會週期性地執行它的垃圾回收程序（<code>gc</code>），它執行之後，使用 <code>git fsck</code> 就不能再看到不可訪問對象了。</p>',29)),e("p",null,[e("em",null,[t[6]||(t[6]=s("本文",-1)),o(i,{href:"http://jvanz.com/recovering-missed-data-from-stash.html#recovering-missed-data-from-stash"},{default:a(()=>[...t[5]||(t[5]=[s("最初發表",-1)])]),_:1}),t[7]||(t[7]=s("於作者的Blog，並得到了轉載授權。",-1))])]),e("p",null,[t[9]||(t[9]=s("（題圖：opensource.com，附圖：José Guilherme Vanz, ",-1)),o(i,{href:"https://creativecommons.org/licenses/by/4.0/"},{default:a(()=>[...t[8]||(t[8]=[s("CC BY",-1)])]),_:1}),t[10]||(t[10]=s("）",-1))]),t[28]||(t[28]=e("hr",null,null,-1)),e("p",null,[t[12]||(t[12]=s("via: ",-1)),o(i,{href:"https://opensource.com/article/17/8/recover-dropped-data-stash"},{default:a(()=>[...t[11]||(t[11]=[s("https://opensource.com/article/17/8/recover-dropped-data-stash",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=s("作者：",-1)),o(i,{href:"https://opensource.com/users/jvanz"},{default:a(()=>[...t[13]||(t[13]=[s("Jose Guilherme Vanz",-1)])]),_:1}),t[17]||(t[17]=s(" 譯者：",-1)),o(i,{href:"https://github.com/firmianay"},{default:a(()=>[...t[14]||(t[14]=[s("firmianay",-1)])]),_:1}),t[18]||(t[18]=s(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[15]||(t[15]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[21]||(t[21]=s("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[19]||(t[19]=[s("LCTT",-1)])]),_:1}),t[22]||(t[22]=s(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:a(()=>[...t[20]||(t[20]=[s("Linux中國",-1)])]),_:1}),t[23]||(t[23]=s(" 榮譽推出",-1))])])}const T=p(g,[["render",u]]);export{C as __pageData,T as default};
